describe('Data Reviewer Table Verification', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/tables');
    });

    it('should verify the table header and rows', () => {
        cy.get('#table1 thead tr').within(() => {
            cy.get('th').eq(0).should('have.text', 'Last Name');
            cy.get('th').eq(1).should('have.text', 'First Name');
            cy.get('th').eq(2).should('have.text', 'Email');
            cy.get('th').eq(3).should('have.text', 'Due');
        });

        cy.get('#table1 tbody tr').should('have.length', 4);
    });

    it('should verify the presence of specific email and last name in the same row', () => {
        cy.get('#table1 tbody tr').each(($row) => {
            cy.wrap($row).within(() => {
                cy.get('td').eq(2).invoke('text').then((email) => {
                    if (email.trim() === 'jsmith@gmail.com') {
                        cy.get('td').eq(0).should('have.text', 'Smith');
                    }
                });
            });
        });
    });
});
